BEGIN;
INSERT INTO mission_bridge_permissions(key,description) VALUES('church_harm.independent_review','Independently review church harm complaints') ON CONFLICT DO NOTHING;
INSERT INTO mission_bridge_role_permissions(role_key,permission_key) VALUES('safeguarding_officer','church_harm.independent_review'),('platform_admin','church_harm.independent_review') ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS mission_bridge_church_harm_profiles(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,owner_user_id TEXT NOT NULL,pseudonym TEXT NOT NULL,original_church_org_id TEXT,share_with_original_church BOOLEAN NOT NULL DEFAULT FALSE,current_stage INTEGER NOT NULL DEFAULT 1 CHECK(current_stage BETWEEN 1 AND 6),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(tenant_id,owner_user_id),CHECK(share_with_original_church=FALSE));
CREATE TABLE IF NOT EXISTS mission_bridge_church_harm_timelines(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,profile_id UUID NOT NULL REFERENCES mission_bridge_church_harm_profiles(id),event_period TEXT NOT NULL,event_summary TEXT NOT NULL,impact_summary TEXT NOT NULL,private BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK(private=TRUE));
CREATE TABLE IF NOT EXISTS mission_bridge_boundary_checklists(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,profile_id UUID NOT NULL REFERENCES mission_bridge_church_harm_profiles(id),coercion_signals JSONB NOT NULL,shame_signals JSONB NOT NULL,authority_signals JSONB NOT NULL,user_notes TEXT NOT NULL DEFAULT '',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS mission_bridge_rebuilding_goals(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,profile_id UUID NOT NULL REFERENCES mission_bridge_church_harm_profiles(id),goal TEXT NOT NULL,participant_confirmed BOOLEAN NOT NULL DEFAULT FALSE,status TEXT NOT NULL DEFAULT 'draft',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS mission_bridge_new_community_assessments(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,profile_id UUID NOT NULL REFERENCES mission_bridge_church_harm_profiles(id),community_alias TEXT NOT NULL,power_safety INTEGER CHECK(power_safety BETWEEN 1 AND 5),complaint_channel BOOLEAN,exit_freedom BOOLEAN,confidentiality_clarity BOOLEAN,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS mission_bridge_church_harm_complaints(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,profile_id UUID NOT NULL REFERENCES mission_bridge_church_harm_profiles(id),summary TEXT NOT NULL,requested_outcome TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'submitted',assigned_independent_reviewer TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS mission_bridge_confidential_healing_groups(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,title TEXT NOT NULL,cross_organization BOOLEAN NOT NULL DEFAULT TRUE,confidentiality_policy TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active');
DO $$ DECLARE t TEXT; BEGIN FOREACH t IN ARRAY ARRAY['mission_bridge_church_harm_profiles','mission_bridge_church_harm_timelines','mission_bridge_boundary_checklists','mission_bridge_rebuilding_goals','mission_bridge_new_community_assessments','mission_bridge_church_harm_complaints','mission_bridge_confidential_healing_groups'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY tenant_isolation ON %I USING (tenant_id=current_setting(''app.tenant_id'',true)) WITH CHECK (tenant_id=current_setting(''app.tenant_id'',true))',t);END LOOP;END $$;
COMMIT;
